Implementação de Pilha em Python — classe
Usando classe orientada a objetos:
class Pilha:
    def __init__(self):
        self._dados = []

    def push(self, item):
        self._dados.append(item)

    def pop(self):
        if self.is_empty():
            raise IndexError("Underflow!")
        return self._dados.pop()

    def peek(self):
        return self._dados[-1]

    def is_empty(self):
        return len(self._dados) == 0

    def size(self):
        return len(self._dados)

# Uso
p = Pilha()
p.push(5)
p.push(10)
print(p.peek())  # 10
print(p.pop())   # 10

Aplicação Prática: Verificador de Parênteses
Um dos usos clássicos de pilhas é a verificação de expressões balanceadas — fundamental em compiladores e parsers de linguagens. O algoritmo percorre a string, empilhando aberturas e verificando fechamentos.
def verificar_parenteses(expressao):
    """Verifica se parênteses, colchetes e chaves estão balanceados."""
    pilha = []
    pares = {')': '(', ']': '[', '}': '{'}
    abertos = set('([{')

    for char in expressao:
        if char in abertos:
            pilha.append(char)        # Empilha abertura
        elif char in pares:
            if not pilha or pilha[-1] != pares[char]:
                return False           # Fechamento inválido
            pilha.pop()                # Desempilha abertura correspondente

    return len(pilha) == 0             # Pilha deve estar vazia ao final

# Testes
print(verificar_parenteses("(a + b) * [c - d]"))  # True
print(verificar_parenteses("(x + [y))"))          # False
print(verificar_parenteses("{V = I * R}"))        # True
Este algoritmo roda em O(n), onde n é o tamanho da expressão. É usado em IDEs, compiladores Python, Java, C++ e em avaliadores de circuitos lógicos.

Implementação de Fila em Python — nó encadeado
Classe Fila com nó encadeado:
class No:
    def __init__(self, dado):
        self.dado = dado
        self.proximo = None

class Fila:
    def __init__(self):
        self.front = None
        self.rear = None
        self._tamanho = 0

    def enqueue(self, item):
        novo = No(item)
        if self.rear:
            self.rear.proximo = novo
        self.rear = novo
        if not self.front:
            self.front = novo
        self._tamanho += 1

    def dequeue(self):
        if not self.front:
            raise IndexError("Fila vazia!")
        dado = self.front.dado
        self.front = self.front.proximo
        if not self.front:
            self.rear = None
        self._tamanho -= 1
        return dado
